-- Counter & Shop Helper (Paladins 8.1, id paladins-smartcounter-81): in-game overlay (Tempest Scripting).
--
--   lib/sc_data.lua      data + constants (generated by engine/export_lua.py, do not edit)
--   lib/sc_predictor.lua Lua port of engine/predictor.py (structured results, no text)
--   lib/sc_detect.lua    light auto-detection (1 Hz, reads only)
--   lib/sc_player.lua    the local player's owned items + ranks (live, read-only, 2 Hz)
--   lib/sc_lang.lua      UI strings EN / FR / DE (Latin-1 only)
--   lib/sc_expected.lua  reference results for `smartcounter_selftest`
--
--   icons/*.png          the game's own shop icons (engine/make_icons.ps1)
--
-- Item / category / role / ability names come from the game's native 8.1 loc tables (sc_data.lua).
-- Cost: detection 1x/s and item reading 4x/s while something is shown, predictor rerun only when
-- the inputs change, drawing = a few ImGui widgets. Mouse captured only while the menu is open.
-- Made by Machi Konno  ·  Discord: machi.konno

local VERSION = "0.6.2"
local AUTHOR, DISCORD = "Machi Konno", "machi.konno"
local TAG = "[smartcounter] "
local function log(fmt, ...)
	tempest.log(TAG .. string.format(fmt, ...))
end

-- 0.5.1: guarded ImGui. Every scoped call (window/table/tab...) runs its body in pcall, so an error
-- never skips the matching End; push/pop stacks are counted and restored to their level on error.
local RAW = ui
local depth = { color = 0, var = 0, font = 0, id = 0, indent = 0 }
local function snap() return depth.color, depth.var, depth.font, depth.id, depth.indent end
local function restore(c, v, f, i, ind)
	if depth.color > c then pcall(RAW.pop_color, depth.color - c) end
	if depth.var > v then pcall(RAW.pop_var, depth.var - v) end
	for _ = f + 1, depth.font do pcall(RAW.pop_font) end
	for _ = i + 1, depth.id do pcall(RAW.pop_id) end
	if depth.indent > ind then pcall(RAW.unindent, depth.indent - ind) end
	depth.color, depth.var, depth.font, depth.id, depth.indent = c, v, f, i, ind
end
local function scoped(name)
	return function(...)
		local args, err = { ... }, nil
		local n = select("#", ...)
		for k = 1, n do
			local fn = args[k]
			if type(fn) == "function" then
				args[k] = function(...)
					local s = { snap() }
					local ok, e = pcall(fn, ...)
					if not ok then
						restore(s[1], s[2], s[3], s[4], s[5])
						err = err or e
					end
				end
			end
		end
		local r = { RAW[name](unpack(args, 1, n)) }
		if err then error(err, 0) end
		return unpack(r)
	end
end
local ui = setmetatable({}, { __index = RAW })
for _, name in ipairs({ "window", "child", "group", "tooltip", "tab_bar", "tab_item", "table", "popup",
	"popup_modal", "popup_context_item", "tree", "menu", "menu_bar", "with_font" }) do
	if RAW[name] then ui[name] = scoped(name) end
end
function ui.push_color(...) RAW.push_color(...) depth.color = depth.color + 1 end
function ui.pop_color(n) n = n or 1 RAW.pop_color(n) depth.color = math.max(0, depth.color - n) end
function ui.push_var(...) RAW.push_var(...) depth.var = depth.var + 1 end
function ui.pop_var(n) n = n or 1 RAW.pop_var(n) depth.var = math.max(0, depth.var - n) end
function ui.push_font(f) RAW.push_font(f) depth.font = depth.font + 1 end
function ui.pop_font() RAW.pop_font() depth.font = math.max(0, depth.font - 1) end
function ui.push_id(x) RAW.push_id(x) depth.id = depth.id + 1 end
function ui.pop_id() RAW.pop_id() depth.id = math.max(0, depth.id - 1) end
function ui.indent(w) RAW.indent(w) depth.indent = depth.indent + (w or 0) end
function ui.unindent(w) RAW.unindent(w) depth.indent = depth.indent - (w or 0) end

