local function copy(v)
	if type(v) ~= "table" then return v end
	local c = {}
	for k, x in pairs(v) do c[k] = copy(x) end
	return c
end

local function fill(dst, d)
	for k, v in pairs(d) do
		if dst[k] == nil or type(dst[k]) ~= type(v) then
			dst[k] = copy(v)
		elseif type(v) == "table" then
			fill(dst[k], v)
		end
	end
end

