-- Game language (read once, read-only).
-- 0.5: the Steam client language comes first. A French Steam client runs Paladins in French while
-- ChaosEngine.ini still says Language=INT (0.4 trusted the ini and stayed in English).
--   1. <library>\steamapps\appmanifest_444090.acf  "language" "french"
--   2. Documents\My Games\Paladins\ChaosGame\Config\ChaosEngine.ini  Language=INT|FRA|DEU
local STEAM_LOC = { french = "fr", german = "de", english = "en", italian = "it", russian = "ru",
	schinese = "zh", tchinese = "zh", japanese = "ja", koreana = "ko", korean = "ko" }
local GAME_LOC = { INT = "en", FRA = "fr", DEU = "de", ITA = "it", RUS = "ru", CHN = "zh", CHT = "zh", JPN = "ja",
	KOR = "ko" }
local function read_steam_lang()
	if not (io and io.open and tempest.game_dir) then return nil end
	local gd = tempest.game_dir()
	if type(gd) ~= "string" then return nil end
	local lib = gd:gsub("[\\/]+$", ""):match("^(.*)[\\/][Cc]ommon[\\/][^\\/]+$")
	if not lib then return nil end
	local f = io.open(lib .. "\\appmanifest_444090.acf", "r")
	if not f then return nil end
	local lang
	for line in f:lines() do
		lang = line:match('^%s*"language"%s*"([%w_]+)"')
		if lang then break end
	end
	f:close()
	return lang and lang:lower()
end
local function read_game_lang()
	if not (io and io.open and os and os.getenv) then return nil end
	local home = os.getenv("USERPROFILE")
	if not home then return nil end
	local rel = "\\My Games\\Paladins\\ChaosGame\\Config\\ChaosEngine.ini"
	for _, docs in ipairs({ home .. "\\Documents", home .. "\\OneDrive\\Documents", home .. "\\OneDrive\\Documenti" }) do
		local f = io.open(docs .. rel, "r")
		if f then
			local code
			for line in f:lines() do
				code = line:match("^%s*Language%s*=%s*(%a+)")
				if code then break end
			end
			f:close()
			if code then return code:upper() end
		end
	end
	return nil
end
local ok_sl, sl = pcall(read_steam_lang)
local ok_gl, gl = pcall(read_game_lang)
local STEAM_LANG = ok_sl and sl or nil       -- e.g. "french"
local GAME_LANG_CODE = ok_gl and gl or nil   -- e.g. "INT"
local GAME_LANG, GAME_LANG_SRC
if STEAM_LANG then
	GAME_LANG, GAME_LANG_SRC = STEAM_LOC[STEAM_LANG] or "en", "steam:" .. STEAM_LANG
elseif GAME_LANG_CODE then
	GAME_LANG, GAME_LANG_SRC = GAME_LOC[GAME_LANG_CODE] or "en", "ini:" .. GAME_LANG_CODE
else
	GAME_LANG, GAME_LANG_SRC = "en", "default"
end

