-- ------------------------------------------------------------------ fonts and theme
-- Segoe UI (Windows) renders far cleaner than the default bitmap font. Loaded once per size;
-- if anything fails we simply keep the default font.
-- 0.3 called ui.add_font at load time: "the UI is not initialised yet (wait for ui.ready())".
-- 0.4 called it inside on_draw: it returned nil (log "fonts: 0/6 loaded").
-- 0.5: at load time when ui.ready() is already true (hot reload), else once ready through
-- tempest.queue (outside the draw callback); TTF first, then the built-in font at that size
-- (add_font(nil, size)). If nothing loads, text size falls back to a per-window font scale.
-- 0.6: one font set per script. "latin" (en fr de it ru): Segoe UI with Latin, Latin Extended,
-- Greek, Cyrillic and punctuation ranges. zh / ja / ko: the same base + a Windows CJK font merged
-- in, limited to the glyphs our strings really use (UI table + the game's own names in that
-- language), so the atlas stays small. The native names of the CJK languages are merged into every
-- set so the language picker reads correctly whatever language is shown.
local FONT_SIZES = { 15, 17, 20 }
local FONT_SCALE = { 1.12, 1.3, 1.55 }   -- default 13 px font -> about 15 / 17 / 20 px
local BASE_RANGES = { 0x0020, 0x024F, 0x0370, 0x03FF, 0x0400, 0x052F, 0x2000, 0x206F, 0x2190, 0x21FF,
	0x2200, 0x22FF, 0x25A0, 0x25FF, 0 }
local CJK_FONTS = {
	zh = { { "msyh.ttc", "msyhbd.ttc" }, { "simhei.ttf", "simhei.ttf" }, { "simsun.ttc", "simsun.ttc" } },
	ja = { { "YuGothM.ttc", "YuGothB.ttc" }, { "meiryo.ttc", "meiryob.ttc" }, { "msgothic.ttc", "msgothic.ttc" } },
	ko = { { "malgun.ttf", "malgunbd.ttf" }, { "gulim.ttc", "gulim.ttc" } },
}
-- Kept in `shared`: a hot reload reuses them instead of growing the font atlas.
local FONT_SETS = S.font_sets or {}
S.font_sets = FONT_SETS
local function font_group(lang)
	return (lang == "zh" or lang == "ja" or lang == "ko") and lang or "latin"
end
local function FS()
	local g = font_group(ui_lang())
	local s = FONT_SETS[g]
	if not s then
		s = { state = "pending", body = {}, bold = {}, group = g }
		FONT_SETS[g] = s
	end
	return s
end
local function file_exists(p)
	local f = io and io.open(p, "rb")
	if f then f:close() return true end
	return false
end
local WIN_FONTS = ((os.getenv and os.getenv("WINDIR")) or "C:\\Windows") .. "\\Fonts\\"

-- UTF-8 code points of a string (LuaJIT has no utf8 library).
local function codepoints(s, out)
	local i, n = 1, #s
	while i <= n do
		local c = s:byte(i)
		local cp, len
		if c < 0x80 then cp, len = c, 1
		elseif c >= 0xF0 then cp, len = c % 0x08, 4
		elseif c >= 0xE0 then cp, len = c % 0x10, 3
		elseif c >= 0xC0 then cp, len = c % 0x20, 2
		else cp, len = nil, 1 end
		if cp and len > 1 then
			for k = 1, len - 1 do
				local b = s:byte(i + k)
				if not b then cp = nil break end
				cp = cp * 64 + (b % 64)
			end
		end
		if cp and cp >= 0x2E80 then out[cp] = true end
		i = i + len
	end
	return out
end
-- Glyph ranges for a CJK language: every string of that language (UI table + game names).
local function cjk_ranges(lang, extra)
	local set = {}
	for _, s in pairs(L.strings(lang) or {}) do
		if type(s) == "string" then codepoints(s, set) end
	end
	local seen = {}
	local function walk(tb, depth)
		if depth > 6 or seen[tb] then return end
		seen[tb] = true
		for k, v in pairs(tb) do
			if k == lang and type(v) == "string" then codepoints(v, set)
			elseif type(v) == "table" then walk(v, depth + 1) end
		end
	end
	walk(DATA, 0)
	if extra then codepoints(extra, set) end
	for cp = 0x3000, 0x303F do set[cp] = true end      -- CJK punctuation
	for cp = 0xFF01, 0xFF5E do set[cp] = true end      -- full-width forms
	local cps = {}
	for cp in pairs(set) do cps[#cps + 1] = cp end
	table.sort(cps)
	local r = {}
	for _, cp in ipairs(cps) do
		if #r > 0 and r[#r] == cp - 1 then r[#r] = cp else r[#r + 1] = cp; r[#r + 1] = cp end
	end
	r[#r + 1] = 0
	return r, #cps
end
local function name_ranges(s)
	local set = codepoints(s, {})
	local cps = {}
	for cp in pairs(set) do cps[#cps + 1] = cp end
	table.sort(cps)
	local r = {}
	for _, cp in ipairs(cps) do r[#r + 1] = cp; r[#r + 1] = cp end
	r[#r + 1] = 0
	return r
end

local function load_fonts(set, how)
	if set.state ~= "pending" and set.state ~= "queued" then return end
	if ui.ready and not ui.ready() then return end
	set.state = "loading"
	local function pick(...)
		for _, name in ipairs({ ... }) do
			if file_exists(WIN_FONTS .. name) then return WIN_FONTS .. name end
		end
	end
	local regular = pick("segoeui.ttf", "arial.ttf")
	local boldf = pick("segoeuib.ttf", "arialbd.ttf") or regular
	local n, last_err, builtin = 0, nil, false
	local function add(path, size)
		local ok, f = pcall(ui.add_font, path, size, { ranges = BASE_RANGES })
		if ok and f then return f end
		ok, f = pcall(ui.add_font, path, size)   -- older Tempest: no options
		if ok and f then return f end
		last_err = ok and "nil" or f
		ok, f = pcall(ui.add_font, nil, size)   -- built-in font at that size
		if ok and f then builtin = true return f end
		return nil
	end
	-- the main CJK font of this set and its glyphs
	local main, glyphs
	if set.group ~= "latin" then
		for _, pair in ipairs(CJK_FONTS[set.group]) do
			local r, b = pick(pair[1]), pick(pair[2])
			if r then main = { r, b or r } break end
		end
		if main then
			local nglyphs
			glyphs, nglyphs = cjk_ranges(set.group)
			set.glyphs = nglyphs
		else
			last_err = "no " .. set.group .. " font in " .. WIN_FONTS
		end
	end
	-- language picker: the native names of the CJK languages, from their own fonts
	local picker = {}
	for _, lg in ipairs({ "zh", "ja", "ko" }) do
		if lg ~= set.group then
			for _, pair in ipairs(CJK_FONTS[lg]) do
				local p = pick(pair[1])
				if p then picker[#picker + 1] = { p, name_ranges(L.native(lg)) } break end
			end
		end
	end
	local function merge(path, size, ranges)
		if path then pcall(ui.add_font, path, size, { merge = true, ranges = ranges }) end
	end
	for i, size in ipairs(FONT_SIZES) do
		local b = regular and add(regular, size)
		if b then
			if main then merge(main[1], size, glyphs) end
			for _, pm in ipairs(picker) do merge(pm[1], size, pm[2]) end
		end
		local h = boldf and add(boldf, size + 2)
		if h then
			if main then merge(main[2], size + 2, glyphs) end
			for _, pm in ipairs(picker) do merge(pm[1], size + 2, pm[2]) end
		end
		if b then set.body[i], n = b, n + 1 end
		if h then set.bold[i], n = h, n + 1 end
	end
	set.name = n == 0 and "scaled default" or (builtin and "built-in" or (regular:match("([^\\]+)$") or "?"))
	if main then set.name = set.name .. " + " .. (main[1]:match("([^\\]+)$") or "?") end
	set.state = n > 0 and "wait" or "failed"   -- usable from the next frame (atlas rebuilt between frames)
	log("fonts %s (%s): %d/%d loaded (%s)%s%s", set.group, how or "load", n, #FONT_SIZES * 2, set.name,
		set.glyphs and string.format(", %d CJK glyphs", set.glyphs) or "",
		last_err and (", last error: " .. tostring(last_err)) or "")
end
-- Hot reload with the UI already up: load now, which is what the API asks for ("at load time").
if FS().state == "pending" and ui.ready and ui.ready() then pcall(load_fonts, FS(), "load time") end

-- Fallback when no font could be added: scale the default font of the current window.
local cur_scale = 1
local function set_scale(s)   -- per window: always applied (each window starts at 1)
	if ui.C and pcall(function() ui.C.igSetWindowFontScale(s) end) then cur_scale = s end
end

local function with_font(kind, fn)
	local set = FS()
	local f = set.state == "ready" and set[kind][cfg.text_size]
	if f then
		ui.push_font(f)
		local ok, err = pcall(fn)
		ui.pop_font()
		if not ok then error(err, 0) end
	elseif set.state == "failed" then
		local prev = cur_scale
		set_scale(FONT_SCALE[cfg.text_size] * (kind == "bold" and 1.08 or 1))
		local ok, err = pcall(fn)
		if kind == "bold" then set_scale(prev) end
		if not ok then error(err, 0) end
	else
		fn()
	end
end

