	Button = { 0.19, 0.21, 0.29, 1 }, ButtonHovered = { 0.30, 0.33, 0.45, 1 }, ButtonActive = { 0.62, 0.46, 0.16, 1 },
	Header = { 0.19, 0.21, 0.29, 1 }, HeaderHovered = { 0.30, 0.33, 0.45, 1 }, HeaderActive = { 0.62, 0.46, 0.16, 1 },
