local function tcol(c, s)
	ui.text_colored(c[1], c[2], c[3], c[4], "%s", s)
end
local function wrapped(c, s)
	if c then ui.push_color(ui.Col.Text, c[1], c[2], c[3], c[4]) end
	ui.text_wrapped("%s", s)
	if c then ui.pop_color(1) end
end
local function bold(c, s)
	with_font("bold", function() tcol(c, s) end)
end

