local function set_menu(on)
	menu_open = on
	if on then PLAYER:refresh() end   -- on demand: read the items now, not at the next 1 s tick
	if on and not cfg.tutorial_done and not tut_step then tut_step = 1 end
	local ok = pcall(ui.capture, on)
	S.captured = on and ok
	if not on then rebinding = nil end
end

local function set_lang(lang)
	if (lang == "auto" or L.valid(lang)) and cfg.lang ~= lang then
		cfg.lang = lang
		L.set(ui_lang())
		mark_dirty()
	end
end

-- Native 8.1 names (game loc tables), English official name as fallback.
local function iname(item)
	local it = item and DATA.items[item]
	return (it and it.names and it.names[ui_lang()]) or item or "?"
end
local function idesc(item)
	local it = item and DATA.items[item]
	return it and it.descs and (it.descs[ui_lang()] or it.descs.en)
end
local function cname(cat)
	local c = DATA.loc_categories[cat]
	return (c and c[ui_lang()]) or t("cat_" .. tostring(cat))
end
local function rname(role)
	local r = DATA.loc_roles[role]
	return (r and r[ui_lang()]) or t("role_" .. tostring(role))
end
local function chname(name)
	local c = name and PRED:champion(name)
	return (c and c.names and c.names[ui_lang()]) or name
end
local ROMAN = { [0] = "0", "I", "II", "III" }
-- Ability name in the UI language (game data), e.g. Makoa a3 = "Ancre de drague".
local function aname(a)
	return a and a.names and (a.names[ui_lang()] or a.names.en) or "?"
end

-- Shop icons (src/icons, the game's own art): loaded on first use, drawn once uploaded.
local MOD_DIR
do
	local ok, list = pcall(tempest.installed)
	if ok and type(list) == "table" then
		for _, m in ipairs(list) do
			if m.id == MOD and m.path then MOD_DIR = m.path end
		end
	end
	if not MOD_DIR and tempest.game_dir then
		local okd, gd = pcall(tempest.game_dir)
		if okd and type(gd) == "string" then MOD_DIR = gd .. "\\.tempest\\v2\\mods\\" .. tostring(MOD) end
	end
end
local ICONS, icons_loaded = {}, 0
local function icon(item)
	local e = ICONS[item]
	if e == nil then
		e = false
		local it = DATA.items[item]
		if it and it.icon and MOD_DIR and ui.load_image then
			local p = MOD_DIR .. "\\" .. it.icon:gsub("/", "\\")
			if file_exists(p) then
				local ok, img = pcall(ui.load_image, p)
				if ok and img then
					e = img
					icons_loaded = icons_loaded + 1
				end
			end
		end
		ICONS[item] = e
	end
	if e then
		local ok, ready = pcall(e.ready, e)
		if ok and ready then return e end
	end
	return nil
end

-- ------------------------------------------------------------------ keys
local key_ids = {}

local function on_action(id)
	if rebinding then return false end
	if id == "menu" then
		set_menu(not menu_open)
	elseif id == "overlay" then
		overlay_on = not overlay_on
	elseif id == "settings" then
		if menu_open and cur_tab == "settings" then
			set_menu(false)
		else
			set_menu(true)
			want_tab = "settings"
		end
	elseif id == "lock" then
		cfg.locked = not cfg.locked
		mark_dirty()
		pcall(tempest.toast, t(cfg.locked and "locked" or "unlocked"))
	elseif id == "layout" then
		-- compact <-> detailed (from Auto: the opposite of what is shown right now)
		local shown = cfg.display
		if shown == "auto" then shown = S.last_mode or "compact" end
		cfg.display = shown == "compact" and "detailed" or "compact"
		overlay_on = true
		mark_dirty()
		pcall(tempest.toast, t("layout_now", t("disp_" .. cfg.display)))
	end
	return true
end

local function bind(id, spec)
	local ok, kid = pcall(tempest.on_key, spec, function() return on_action(id) end)
	if ok and kid then
		key_ids[id] = kid
		return true
	end
	return false, tostring(kid)
end

local function unbind(id)
	if key_ids[id] then pcall(tempest.off_key, key_ids[id]) end
	key_ids[id] = nil
end

local function rebind(id, spec)
	for _, a in ipairs(ACTIONS) do
		if a ~= id and cfg.keys[a] == spec then
			return false, t("key_in_use", spec, t("act_" .. a))
		end
	end
	local old = cfg.keys[id]
	unbind(id)
	local ok, err = bind(id, spec)
	if ok then
		cfg.keys[id] = spec
		mark_dirty()
		return true
	end
	bind(id, old)
	return false, t("key_refused", tostring(err))
end

for _, a in ipairs(ACTIONS) do
	if not bind(a, cfg.keys[a]) then
		log("invalid key %s for %s, back to %s", tostring(cfg.keys[a]), a, DEFAULT_KEYS[a])
		cfg.keys[a] = DEFAULT_KEYS[a]
		bind(a, cfg.keys[a])
		mark_dirty()
	end
end

-- Keys offered for rebinding (all on a 60% keyboard; F-keys via Fn): ImGui name -> Tempest name.
local CAPTURE_KEYS = {}
for c = 65, 90 do CAPTURE_KEYS[#CAPTURE_KEYS + 1] = { string.char(c), string.char(c) } end
for i = 0, 9 do CAPTURE_KEYS[#CAPTURE_KEYS + 1] = { tostring(i), tostring(i) } end
for i = 1, 12 do CAPTURE_KEYS[#CAPTURE_KEYS + 1] = { "F" .. i, "F" .. i, fkey = true } end
for _, p in ipairs({ { "Semicolon", "Semicolon" }, { "GraveAccent", "Tilde" }, { "Minus", "Minus" },
	{ "Equal", "Equals" }, { "LeftBracket", "LeftBracket" }, { "RightBracket", "RightBracket" },
	{ "Apostrophe", "Quote" }, { "Comma", "Comma" }, { "Period", "Period" }, { "Slash", "Slash" },
	{ "Backslash", "Backslash" } }) do
	CAPTURE_KEYS[#CAPTURE_KEYS + 1] = p
end

local function kdown(name)
	local k = ui.Key[name]
	return k ~= nil and ui.key_down(k)
end
local function kpressed(name)
	local k = ui.Key[name]
	return k ~= nil and ui.key_pressed(k, false)
end

-- Polled while an action is being rebound (menu open).
local function poll_rebind()
	if kpressed("Escape") then
		rebinding, rebind_msg, rebind_ok = nil, t("key_cancelled"), true
		return
	end
	for _, k in ipairs(CAPTURE_KEYS) do
		if kpressed(k[1]) then
			local ctrl = kdown("LeftCtrl") or kdown("RightCtrl")
			local shift = kdown("LeftShift") or kdown("RightShift")
			local alt = kdown("LeftAlt") or kdown("RightAlt")
			if not (ctrl or shift or alt or k.fkey) then
				rebind_msg, rebind_ok = t("key_need_mod"), false
				return
			end
			local spec = (ctrl and "Ctrl+" or "") .. (shift and "Shift+" or "") .. (alt and "Alt+" or "") .. k[2]
			local id = rebinding
			rebinding = nil
			local ok, err = rebind(id, spec)
			rebind_msg, rebind_ok = ok and t("key_saved", spec) or err, ok
			return
		end
	end
end

-- ------------------------------------------------------------------ inputs -> prediction
local NAMES = {}
for _, c in ipairs(DATA.champions) do NAMES[#NAMES + 1] = c.name end
table.sort(NAMES)
local ROLES = { "", "Frontline", "Damage", "Flank", "Support" }

local last_cs_me      -- my pick seen in champion select (kept for the start of the match)
local result, result_err, result_sig, inputs
local changed_at      -- last time the build / enemies changed (Auto layout)
local last_status

local function in_match()
	return cfg.auto_detect and DET.state.status == "match"
end

-- Owned items: live reading when it recognises something, else the manual fallback.
local function owned_items()
	local st = PLAYER.state
	if cfg.live_items and st.available then return st.owned, "live" end
	if next(cfg.owned) then return cfg.owned, "manual" end
	return {}, "none"
end

local function resolve_inputs(st)
	local me = cfg.manual.me ~= "" and cfg.manual.me or nil
	if not me and cfg.auto_detect then me = st.me or last_cs_me end
	local enemies, seen, manual_n = {}, {}, 0
	for _, n in ipairs(cfg.manual.enemies) do
		if n ~= "" and not seen[n] and #enemies < DATA.max_enemies then
			enemies[#enemies + 1], seen[n] = n, true
			manual_n = manual_n + 1
		end
	end
	if cfg.auto_detect then
		for _, n in ipairs(st.enemies or {}) do
			if not seen[n] and #enemies < DATA.max_enemies then enemies[#enemies + 1], seen[n] = n, true end
		end
	end
	local phase = cfg.phase ~= "auto" and cfg.phase or (cfg.auto_detect and st.phase) or nil
	if not phase then phase = (st.status == "champ_select" or st.status == "lobby") and "early" or "mid" end
	local mode = cfg.mode ~= "auto" and cfg.mode or (cfg.auto_detect and st.mode) or nil
	return { me = me, enemies = enemies, manual_n = manual_n, phase = phase, mode = mode,
		phase_auto = cfg.phase == "auto", mode_auto = cfg.mode == "auto", style = cfg.style }
end

local function update_result()
	inputs = resolve_inputs(DET.state)
	local owned, src = owned_items()
	local onames = {}
	for k, v in pairs(owned) do onames[#onames + 1] = k .. "=" .. tostring(v) end
	table.sort(onames)
	inputs.owned, inputs.owned_src = owned, src
	local sig = table.concat({ inputs.me or "", table.concat(inputs.enemies, ","), inputs.phase, inputs.mode or "",
		inputs.style, table.concat(onames, ",") }, "|")
	if sig == result_sig then return end
	result_sig = sig
	changed_at = os.clock()
	result, result_err = nil, nil
	-- errors are kept as { key, arg } and translated when drawn (a language switch applies at once)
	if not inputs.me then
		result_err = { "need_champ" }
	elseif #inputs.enemies == 0 then
		result_err = { "no_enemy" }
	else
		local ok, r, code, detail = pcall(PRED.predict, PRED, inputs.me, inputs.enemies, inputs.phase, inputs.mode,
			inputs.style, owned)
		if not ok then
			result_err = { "err_internal", tostring(r) }
			log("predict failed: %s", tostring(r))
		elseif not r then
			result_err = { "err_" .. tostring(code), tostring(detail or "") }
		else
			result = r
		end
	end
end

local function err_text()
	if not result_err then return nil end
	return result_err[2] and t(result_err[1], result_err[2]) or t(result_err[1])
end

-- ------------------------------------------------------------------ text from structured results
local function lvl(n) return t("lvl", n) end

local function reason_text(r)
	if not r then return nil end
	local txt = t("r_" .. tostring(r.key), r.args or "")
	return r.enemy and (r.enemy .. ": " .. txt) or txt
end

-- Why an item is suggested. full=false: the main reason only (overlay), full=true: everything (menu).
local function why_text(item, why, full)
	local parts = {}
	if why then
		local rt = reason_text(why.reason)
		if rt then parts[#parts + 1] = rt end
		if why.arch then
			parts[#parts + 1] = t("why_arch", t((full and "arch_" or "archs_") .. why.arch.key), why.arch.probability)
		end
		if (why.own or 0) > 0 then parts[#parts + 1] = t("why_own", t("style_" .. tostring(why.style))) end
	end
	if full then
		local note = L.maybe("note_" .. item)
		if note then parts[#parts + 1] = note end
	elseif #parts > 1 then
		parts = { parts[1] }
	end
	if #parts == 0 then return t("r_generic") end
	return table.concat(parts, "  ·  ")
end

-- What makes an enemy dangerous, with the champion's own abilities (game data) instead of a
-- generic word: "Makoa: Ancre de drague (étourdit)", "Lian: dégâts explosifs (Chute des dieux)".
-- An ability backing several tags is named once: "Grohk: Totem de guérison (soigne, déployable)".
local function threat_parts(th, n)
	local parts, by_slot = {}, {}
	for i, tg in ipairs(th.tags) do
		if i > n then break end
		local a
		for _, x in ipairs(th.abilities or {}) do
			if x.tag == tg then a = x end
		end
		if a and by_slot[a.slot] then
			local p = by_slot[a.slot]
			p.fx[#p.fx + 1] = a.fx and t("fx_" .. a.fx) or t("tag_" .. tg)
		elseif a then
			local p = { name = aname(a), fx = { a.fx and t("fx_" .. a.fx) or t("tag_" .. tg) } }
			by_slot[a.slot] = p
			parts[#parts + 1] = p
		else
			parts[#parts + 1] = { text = t("tag_" .. tg) }
		end
	end
	local out = {}
	for _, p in ipairs(parts) do
		out[#out + 1] = p.text or (p.name .. " (" .. table.concat(p.fx, ", ") .. ")")
	end
	return out
end

-- short=true: first tag only, no "(not in your items)" (panel); false: up to 3 tags (menu).
local function threat_text(th, short)
	local tags = threat_parts(th, short and 1 or 3)
	local s = chname(th.name) .. ": " .. (#tags > 0 and table.concat(tags, ", ") or t("r_generic"))
	if th.answer then
		s = s .. "  ->  " .. iname(th.answer) .. ((th.answer_in_build or short) and "" or (" " .. t("not_in_build")))
	end
	return s
end

-- Where we are: draft (champion select: picks still possible), match (champion locked), plan.
local function context()
	local st = cfg.auto_detect and DET.state.status
	if st == "match" then return "match" end
	if st == "champ_select" then return "draft" end
	return "plan"
end
local BADGE_COLOR = { draft = C_GOOD, match = C_ACCENT, plan = C_DIM }

local function slot_status(b)
	if b.status == "buy" then return t("status_buy") end
	if b.status == "upgrade" then return t("status_upgrade", ROMAN[b.rank], ROMAN[b.target]) end
	return t("status_done", ROMAN[b.rank])
end

local function danger_color(d)
	if d >= 11 then return C_HIGH elseif d >= 8 then return C_MED end
	return C_LOW
end

local function header_text(long)
	local style = result and result.style
	local parts = { chname(inputs.me) or t("need_champ") }
	if long and result then parts[1] = parts[1] .. " (" .. rname(result.player.role) .. ")" end
	if style then parts[#parts + 1] = t("style_" .. style) end
	parts[#parts + 1] = t("phase_" .. inputs.phase) .. (inputs.phase_auto and "*" or "")
	if long then
		parts[#parts + 1] = inputs.mode and (t("mode_" .. inputs.mode) .. (inputs.mode_auto and "*" or "")) or t("mode_unknown")
	end
	return table.concat(parts, "  ·  ")
end

-- The header already says "Pick your champion" when none is known: not repeated here (0.4 showed it twice).
local function waiting_block()
	local e = result_err and result_err[1] ~= "need_champ" and err_text()
	wrapped(C_DIM, (e and (e .. "  ·  ") or "") .. t("press_menu", cfg.keys.menu))
end

-- ------------------------------------------------------------------ overlay
-- Every line is either wrapped (text_wrapped) or an atomic "chip" whose width was measured, and
-- the window width is computed from the measured text of the active language: nothing can run
-- past the right edge, and an item number can never be left alone at the end of a line.
local CHIP_PAD, CHIP_GAP, ICON_GAP = 9, 8, 3
local ICON_RATIO = 256 / 196                 -- the game's item card art
-- 0.5 colours by rank progress: grey = not owned, amber = rank rising, green = advised rank
-- reached; blue background = optional (flex) slot.
local C_CHIP_BG = { 0.22, 0.23, 0.27, 1 }     -- grey: not owned
local C_CHIP_FLEX = { 0.12, 0.24, 0.44, 1 }   -- blue: optional slot
local C_FILL_PART = { 0.80, 0.55, 0.14, 1 }   -- amber: rank below the advised one
local C_FILL_DONE = { 0.24, 0.58, 0.30, 1 }   -- green: rank >= advised
local C_FLEX_TEXT = { 0.55, 0.75, 1.0, 1 }

local function avail_w()
	local ok, w = pcall(ui.content_region_avail)
	if ok and type(w) == "number" and w > 0 then return w end
	return (ui.window_width() or 300) - 24
end

-- "Résilience III" (to buy), "Résilience II/III" (upgrade), "Agile I · option" (5th, optional).
-- 0.6: no leading order number (reading order already gives it).
local function chip_label(b)
	local rank
	if b.rank > 0 and b.rank < b.target then
		rank = ROMAN[b.rank] .. "/" .. ROMAN[b.target]
	else
		rank = ROMAN[math.max(b.rank, b.target)]
	end
	local s = iname(b.item) .. " " .. rank
	if b.kind == "flex" then s = s .. "  ·  " .. t("flex_tag") end
	return s
end

-- Dashed outline (the optional 5th slot): drawn over the last item's rectangle.
local C_FLEX_LINE = ui.rgb and select(2, pcall(ui.rgb, 0x7FB2FF, 0.95)) or nil
local function dashed_rect(x1, y1, x2, y2)
	if not (ui.dl and ui.dl.line and C_FLEX_LINE) then return end
	local dash, gap = 5, 3
	local function seg(ax, ay, bx, by)
		local len = math.max(math.abs(bx - ax), math.abs(by - ay))
		local d = 0
		while d < len do
			local e = math.min(len, d + dash)
			local f1, f2 = d / len, e / len
			ui.dl.line(ax + (bx - ax) * f1, ay + (by - ay) * f1, ax + (bx - ax) * f2, ay + (by - ay) * f2, C_FLEX_LINE, 1.5)
			d = e + gap
		end
	end
	seg(x1, y1, x2, y1); seg(x2, y1, x2, y2); seg(x2, y2, x1, y2); seg(x1, y2, x1, y1)
end

-- Width of the whole chip (icon + bar), bar width, height.
local function chip_size(label, item)
	local w, h = ui.calc_text_size(label)
	h = math.ceil(h + 6)
	local bw = math.ceil(w + 2 * CHIP_PAD)
	local iw = (item and icon(item)) and (math.floor(h * ICON_RATIO) + ICON_GAP) or 0
	return bw + iw, bw, h, iw
end

local function item_tooltip(b)
	if not (ui.is_item_hovered and ui.is_item_hovered()) then return end
	local lines = { iname(b.item) .. "  ·  " .. cname(b.category) }
	local d = idesc(b.item)
	if d then lines[#lines + 1] = d end
	pcall(ui.set_tooltip, "%s", table.concat(lines, "\n"))
end

local function draw_chip(b, label, w, h)
	local img = icon(b.item)
	if img then
		local iw = math.floor(h * ICON_RATIO)
		if pcall(ui.image, img, iw, h) then
			item_tooltip(b)
			ui.same_line(0, ICON_GAP)
			w = w - iw - ICON_GAP
		end
	end
	local frac = b.target > 0 and math.min(1, b.rank / b.target) or 0
	local bg = b.kind == "flex" and C_CHIP_FLEX or C_CHIP_BG
	local fill = b.rank >= b.target and C_FILL_DONE or C_FILL_PART
	ui.push_color(ui.Col.FrameBg, bg[1], bg[2], bg[3], bg[4])
	ui.push_color(ui.Col.PlotHistogram, fill[1], fill[2], fill[3], fill[4])
	local nc, nv = 2, 0
	if b.next then
		ui.push_color(ui.Col.Border, C_ACCENT[1], C_ACCENT[2], C_ACCENT[3], 1)
		nc = 3
		if ui.StyleVar.FrameBorderSize and pcall(ui.push_var, ui.StyleVar.FrameBorderSize, 2) then nv = 1 end
	end
	local ok = pcall(ui.progress_bar, frac, math.max(20, w), h, label)
	if nv > 0 then ui.pop_var(nv) end
	ui.pop_color(nc)
	if ok then
		if b.kind == "flex" and ui.item_rect_min then
			local okr, x1, y1 = pcall(ui.item_rect_min)
			local okm, x2, y2 = pcall(ui.item_rect_max)
			if okr and okm and x1 and x2 then pcall(dashed_rect, x1, y1, x2, y2) end
		end
		item_tooltip(b)
	else
		tcol(b.rank >= b.target and C_GOOD or (b.kind == "flex" and C_FLEX_TEXT or C_DIM), label)
	end
end

-- Chips in reading order, wrapping only between chips.
local function chip_flow(build)
	local avail, used = avail_w(), 0
	for i, b in ipairs(build) do
		local label = chip_label(b)
		local w, _, h = chip_size(label, b.item)
		w = math.min(w, avail)
		if i > 1 and used + CHIP_GAP + w <= avail then
			ui.same_line()
			used = used + CHIP_GAP + w
		else
			used = w
		end
		draw_chip(b, label, w, h)
	end
end

local function owned_count(build)
	local n = 0
	for _, b in ipairs(build) do
		if b.rank > 0 then n = n + 1 end
	end
	return n
end

local function draw_badge()
	local c = context()
	wrapped(BADGE_COLOR[c], t("badge_" .. c))
end

local function draw_compact()
	bold(C_ACCENT, header_text(false))
	if not result then return waiting_block() end
	chip_flow(result.build)
	local th = result.threats[1]
	if th then
		tcol(danger_color(th.danger), t("watch"))
		ui.same_line()
		local s = threat_text(th, true)
		local th2 = result.threats[2]
		if th2 then s = s .. "   +" .. chname(th2.name) end
		wrapped(nil, s)
	end
	if context() ~= "match" then
		local names = {}
		for i = 1, math.min(3, #result.counters.picks) do names[i] = chname(result.counters.picks[i].name) end
		wrapped(C_GOOD, t("counters") .. ": " .. table.concat(names, ", "))
	end
end

local function draw_counters(full)
	local c = result.counters
	ui.separator_text(t("counters"))
	if full then wrapped(C_DIM, t("counters_hint")) end
	for i = 1, math.min(full and 5 or 3, #c.picks) do
		local p = c.picks[i]
		local why = {}
		for k, key in ipairs(p.why) do
			if full or k == 1 then why[#why + 1] = t("c_" .. key) end
		end
		tcol(C_GOOD, chname(p.name))
		ui.same_line()
		local info = full and ("(" .. rname(p.role) .. ", " .. p.tier .. ")  ") or ""
		wrapped(C_DIM, info .. table.concat(why, "; "))
	end
	if full then
		local roles = {}
		for _, r in ipairs(c.recommended_roles) do roles[#roles + 1] = rname(r) end
		wrapped(C_DIM, t("roles", table.concat(roles, ", ")))
		if #c.enemy_holes > 0 then
			local holes = {}
			for _, h in ipairs(c.enemy_holes) do holes[#holes + 1] = rname(h) end
			wrapped(C_DIM, t("holes", table.concat(holes, ", ")))
		end
	end
end

-- Detailed view; full=true in the menu (all explanations, descriptions, all threats, forecast).
local function draw_detailed(full)
	bold(C_ACCENT, header_text(true))
	draw_badge()
	if not result then return waiting_block() end
	if full then wrapped(C_DIM, t("vs", table.concat(result.enemies, ", "))) end
	local n_owned = owned_count(result.build)
	ui.separator_text(t("buy") .. (n_owned > 0 and ("  ·  " .. t("owned_n", n_owned, #result.build)) or ""))
	for _, b in ipairs(result.build) do
		local label = chip_label(b)
		local w, _, h = chip_size(label, b.item)
		draw_chip(b, label, math.min(w, avail_w()), h)
		local parts = { cname(b.category), slot_status(b) }
		if b.next then parts[2] = t("next_buy") .. ": " .. parts[2] end
		if b.kind == "flex" then parts[#parts + 1] = t("flex_long") end
		if b.offmeta then parts[#parts + 1] = t("offmeta") end
		if b.synergy and #b.synergy > 0 then
			local names = {}
			for i, n in ipairs(b.synergy) do names[i] = iname(n) end
			parts[#parts + 1] = t("synergy", table.concat(names, ", "))
		end
		if full and b.alt then parts[#parts + 1] = t("alt", iname(b.alt)) end
		ui.indent(CHIP_PAD)
		local col = b.next and C_ACCENT or (b.kind == "flex" and C_FLEX_TEXT) or C_DIM
		wrapped(col, table.concat(parts, "  ·  "))
		-- the panel explains only the next purchase; the menu explains everything
		if full or (b.next and b.kind == "primary") then wrapped(nil, why_text(b.item, b.why, full)) end
		if full then
			local d = idesc(b.item)
			if d then wrapped(C_DIM, t("desc", d)) end
		end
		ui.unindent(CHIP_PAD)
	end
	ui.separator_text(t("threats"))
	for i = 1, math.min(full and 5 or 2, #result.threats) do
		local th = result.threats[i]
		local dc = danger_color(th.danger)
		ui.push_color(ui.Col.Text, dc[1], dc[2], dc[3], 1)
		ui.bullet()
		ui.pop_color(1)
		ui.same_line()
		wrapped(nil, threat_text(th, not full))
	end
	if full then
		ui.separator_text(t("forecast"))
		local fc = {}
		for _, a in ipairs(result.forecast) do
			if a.probability >= 30 then fc[#fc + 1] = t("archs_" .. a.key) .. " " .. a.probability .. "%" end
		end
		wrapped(nil, #fc > 0 and table.concat(fc, "  ·  ") or "-")
	end
	if context() == "match" then
		if full then wrapped(C_DIM, t("hidden_in_match")) end
	else
		draw_counters(full)
	end
end

-- Auto: detailed outside a match; in a match detailed for a few seconds after each change
-- (new enemy seen, purchase, phase), then compact. Small screens stay compact in a match.
local AUTO_DETAIL_SECONDS = 8
local function display_mode(now, sw)
	if cfg.display ~= "auto" then return cfg.display end
	if context() ~= "match" then return "detailed" end
	if sw >= 1280 and changed_at and now - changed_at < AUTO_DETAIL_SECONDS then return "detailed" end
	return "compact"
end

-- Natural width of the overlay content in the current font and language, clamped to the screen.
local width_cache, width_n = {}, 0
local function overlay_width(sw, mode)
	local key = table.concat({ result_sig or "", ui_lang(), cfg.text_size, mode, context(), FS().state, FS().group,
		err_text() or "", icons_loaded }, "|")
	local hit = width_cache[key]
	if hit then return hit end
	local pad = 2 * 12 + 4
	local widest_chip, natural = 0, 0
	local widths = {}
	local function fit(s, extra)
		local w = ui.calc_text_size(s)
		natural = math.max(natural, w + (extra or 0))
	end
	with_font("bold", function() fit(header_text(mode ~= "compact")) end)
	if not result then
		fit(t("press_menu", cfg.keys.menu) .. "  ·  " .. (err_text() or ""))
	else
		for i, b in ipairs(result.build) do
			widths[i] = chip_size(chip_label(b), b.item)
			widest_chip = math.max(widest_chip, widths[i])
		end
	end
	local lo = math.max(mode == "compact" and 200 or 300, widest_chip + pad)
	local hi = math.max(lo, math.floor(sw * (mode == "compact" and 0.30 or 0.34)))
	if result then
		if mode == "compact" then
			-- 0.6: width = the widest line once the chips wrap inside the cap, exactly as chip_flow
			-- draws them: no empty band on the right whatever the language (threat lines wrap).
			local cap, line, widest_line = hi - pad, 0, 0
			for i, w in ipairs(widths) do
				if i > 1 and line + CHIP_GAP + w <= cap then line = line + CHIP_GAP + w else line = w end
				widest_line = math.max(widest_line, line)
			end
			natural = math.max(natural, widest_line)
		else
			fit(t("badge_" .. context()))
			natural = math.max(natural, widest_chip)
			for i = 1, math.min(2, #result.threats) do fit(threat_text(result.threats[i], true), 22) end
		end
	end
	local w = math.floor(math.max(lo, math.min(hi, natural + pad)))
	width_n = width_n + 1
	if width_n > 64 then width_cache, width_n = {}, 1 end
	width_cache[key] = w
	return w
end

local last_overlay_h = 0
local function draw_overlay(now)
	local sw, sh = ui.screen()
	local mode = display_mode(now, sw)
	S.last_mode = mode
	local w
	with_font("body", function() w = overlay_width(sw, mode) end)
	-- 0.6: a width dragged by hand (menu open, panel unlocked) wins over the automatic one
	local manual_w = type(cfg.overlay_w) == "table" and tonumber(cfg.overlay_w[mode]) or 0
	if manual_w and manual_w > 0 then w = math.floor(math.max(160, math.min(sw - 16, manual_w))) end
	local x = cfg.pos_x >= 0 and cfg.pos_x or (sw - w - 24)
	local y = cfg.pos_y >= 0 and cfg.pos_y or math.floor(sh * 0.18)
	x = math.max(0, math.min(x, sw - w))
	y = math.max(0, math.min(y, sh - math.max(60, last_overlay_h) - 8))
	local draggable = menu_open and not cfg.locked
	local flags = bor(WF.NoTitleBar, WF.NoCollapse, WF.NoSavedSettings, WF.NoFocusOnAppearing, WF.NoNav,
		WF.NoScrollbar, WF.NoScrollWithMouse or 0)
	if not draggable then flags = bor(flags, WF.NoInputs, WF.NoMove, WF.NoResize) end
	if not draggable or not was_draggable then ui.set_next_window_pos(x, y, COND.Always) end
	was_draggable = draggable
	ui.set_next_window_size(w, 0, COND.Always)   -- height 0 = fit the content (no scrolling)
	ui.set_next_window_bg_alpha(cfg.opacity)
	ui.window("##smartcounter_overlay", { flags = flags }, function()
		with_font("body", function()
			if mode == "compact" then draw_compact() else draw_detailed(false) end
			if draggable then
				wrapped(C_DIM, t("drag_hint", cfg.keys.lock))
				local wx, wy = ui.window_pos()
				if math.abs(wx - x) > 1 or math.abs(wy - y) > 1 then
					cfg.pos_x, cfg.pos_y = math.floor(wx), math.floor(wy)
					mark_dirty()
				end
				-- edge dragged: remember this width for this layout (Settings: "Automatic width")
				local okw, ww = pcall(ui.window_width)
				if okw and type(ww) == "number" and math.abs(ww - w) > 2 and type(cfg.overlay_w) == "table" then
					cfg.overlay_w[mode] = math.floor(ww)
					mark_dirty()
				end
			end
			if ui.window_height then
				local ok, h = pcall(ui.window_height)
				if ok and type(h) == "number" then last_overlay_h = h end
			end
		end)
	end)
end

-- ------------------------------------------------------------------ tip
local TIP_SECONDS = 10
local function draw_tip(now)
	if not tip_start then tip_start = now end
	local el = now - tip_start
	if el > TIP_SECONDS then
		S.tip_done = true
		return
	end
	local a = el > TIP_SECONDS - 2 and (TIP_SECONDS - el) / 2 or 1
	local msg = t("tip", cfg.keys.menu, cfg.keys.overlay)
	with_font("body", function()
		local sw, sh = ui.screen()
		local tw, th = ui.calc_text_size(msg)
		local x, y = math.floor((sw - tw) / 2), math.floor(sh * 0.08)
		ui.fg.rect_filled(x - 14, y - 8, x + tw + 14, y + th + 8, ui.rgb(0x0F1118, 0.78 * a), 7)
		ui.fg.rect(x - 14, y - 8, x + tw + 14, y + th + 8, ui.rgb(0xDBA43C, 0.6 * a), 7, 1)
		ui.fg.text(x, y, ui.rgb(0xFFD266, a), "%s", msg)
	end)
end

