-- 0.6: 8 languages -> one combo (radio buttons no longer fit on a line).
local function lang_picker(id)
	local labels, keys, cur = { t("lang_auto", L.native(GAME_LANG)) }, { "auto" }, 1
	for _, l in ipairs(L.LANGS) do
		labels[#labels + 1], keys[#keys + 1] = l[2], l[1]
		if cfg.lang == l[1] then cur = #keys end
	end
	ui.set_next_item_width(260)
	local i, ch = ui.combo("##lang_" .. id, cur, labels)
	if ch and keys[i] then set_lang(keys[i]) end
end

-- Manual fallback for owned items: the shop grid (4 categories x 5, shop order), one rank slider
-- per item (0 = not owned). 0.5: several items of a category can be owned.
local ITEMS_BY_CAT = {}
for _, name in ipairs(DATA.item_order) do
	local c = DATA.items[name].category or "Other"
	ITEMS_BY_CAT[c] = ITEMS_BY_CAT[c] or {}
	table.insert(ITEMS_BY_CAT[c], name)
end

local function owned_editor()
	ui.table("sc_owned", 4, { flags = ui.TableFlags.SizingStretchSame or 0 }, function()
		for _, cat in ipairs(DATA.item_categories) do
			ui.table_next_column()
			tcol(C_ACCENT, cname(cat))
			for _, n in ipairs(ITEMS_BY_CAT[cat] or {}) do
				ui.push_id("own_" .. n)
				local r = cfg.owned[n] or 0
				ui.text("%s", iname(n))
				ui.set_next_item_width(-1)
				local v, c = ui.slider_int("##rank", r, 0, 3, r == 0 and "-" or ROMAN[r])
				if c then
					v = math.max(0, math.min(3, v))
					cfg.owned[n] = v > 0 and v or nil
					mark_dirty()
				end
				ui.pop_id()
			end
		end
	end)
