local function owned_section()
	ui.separator_text(t("owned_hdr"))
	local st = PLAYER.state
	if cfg.live_items and st.available then
		local names = {}
		for n, r in pairs(st.owned) do names[#names + 1] = iname(n) .. " " .. ROMAN[r] end
		table.sort(names)
		wrapped(C_GOOD, t("owned_live", st.source))
		wrapped(nil, #names > 0 and table.concat(names, ", ") or t("owned_none"))
	else
		wrapped(C_DIM, t("owned_manual"))
		if cfg.live_items then wrapped(C_DIM, t("owned_wait")) end
		owned_editor()
		wrapped(C_DIM, t("owned_hint"))
	end
