local function draw_tutorial(mx, my, mw)
	local sw = ui.screen()
	local tw = math.floor(340 * ({ 0.92, 1.0, 1.16 })[cfg.text_size])
	local tx = (mx + mw + tw + 16 < sw) and (mx + mw + 12) or math.max(0, mx - tw - 12)
	ui.set_next_window_pos(tx, my, COND.Always)
	ui.set_next_window_size(tw, 0, COND.Always)
	local text = t("tut" .. tut_step)
	if tut_step == 3 then text = t("tut3", cfg.keys.overlay, cfg.keys.layout, cfg.keys.lock) end
	if tut_step == 4 then text = t("tut4", cfg.keys.settings) end
	local open = ui.window(t("tut", tut_step, TUT_STEPS) .. "###sc_tuto",
		{ open = true, flags = bor(WF.NoCollapse, WF.NoSavedSettings, WF.NoResize, WF.NoFocusOnAppearing) },
		function()
			with_font("body", function()
				bold(C_ACCENT, t("tut" .. tut_step .. "_t"))
				wrapped(nil, text)
				if tut_step == 1 then lang_picker("tut") end
				ui.spacing()
				if tut_step > 1 then
					if ui.button(t("tut_prev")) then tut_step = tut_step - 1 end
					ui.same_line()
				end
				if tut_step < TUT_STEPS then
					if ui.button(t("tut_next")) then tut_step = tut_step + 1 end
					ui.same_line()
					if ui.button(t("tut_skip")) then end_tutorial() end
				elseif ui.button(t("tut_done")) then
					end_tutorial()
				end
			end)
		end)
	if open == false then end_tutorial() end
end

-- ------------------------------------------------------------------ menu
local function filtered_names(current)
	local list = { "(" .. t("auto") .. ")" }
	local role = ROLES[role_filter]
	local has_current = current == ""
	for _, n in ipairs(NAMES) do
		if role == "" or PRED:champion(n).role == role then
			list[#list + 1] = n
			if n == current then has_current = true end
		end
	end
	if not has_current then table.insert(list, 2, current) end
	local idx = 1
	for i, n in ipairs(list) do
		if n == current then idx = i end
	end
	return list, idx
end

local function champ_combo(label, current)
	local list, idx = filtered_names(current)
	local ni, changed = ui.combo(label, idx, list)
	if changed then return ni == 1 and "" or list[ni], true end
	return current, false
end

local function status_text(st)
	if not cfg.auto_detect then return t("st_off") end
	local parts = { t("st_auto", t("st_" .. tostring(st.status))) }
	if st.map then parts[#parts + 1] = st.map end
	if st.me then parts[#parts + 1] = t("st_me", st.me) end
	if #(st.enemies or {}) > 0 then parts[#parts + 1] = t("st_enemies", #st.enemies) end
	return table.concat(parts, "  ·  ")
end

local function tab_match()
	wrapped(C_DIM, status_text(DET.state))
	ui.separator_text(t("my_champion"))
	ui.set_next_item_width(220)
	local me, ch = champ_combo("##me", cfg.manual.me)
	if ch then cfg.manual.me = me; mark_dirty() end
	if cfg.manual.me == "" then
		ui.same_line()
		ui.text_disabled("%s", t("auto") .. ": " .. tostring(DET.state.me or last_cs_me or t("not_detected")))
	end
	local styles = PRED:styles_for(inputs and inputs.me)
	if #styles > 1 then
		ui.align_text_to_frame_padding()
		ui.text("%s", t("playstyle"))
		ui.same_line()
		if ui.radio(t("auto") .. "##st", cfg.style == "auto") then cfg.style = "auto"; mark_dirty() end
		for _, s in ipairs(styles) do
			ui.same_line()
			if ui.radio(t("style_" .. s) .. "##st", cfg.style == s) then cfg.style = s; mark_dirty() end
		end
		wrapped(C_DIM, t("playstyle_hint"))
	end
	ui.separator_text(t("enemies_hdr"))
	local role_items = {}
	for i, r in ipairs(ROLES) do role_items[i] = r == "" and t("all_roles") or rname(r) end
	ui.set_next_item_width(180)
	local rf, rch = ui.combo(t("role_filter"), role_filter, role_items)
	if rch then role_filter = rf end
	ui.table("sc_enemies", 2, { flags = ui.TableFlags.SizingStretchSame or 0 }, function()
		for i = 1, DATA.max_enemies do
			ui.table_next_column()
			ui.set_next_item_width(-1)
			local v, c = champ_combo("##enemy" .. i, cfg.manual.enemies[i])
			if c then cfg.manual.enemies[i] = v; mark_dirty() end
		end
		ui.table_next_column()
		if ui.button(t("clear_all"), -1, 0) then
			cfg.manual.me = ""
			for i = 1, DATA.max_enemies do cfg.manual.enemies[i] = "" end
			mark_dirty()
		end
	end)
	if inputs and #inputs.enemies > inputs.manual_n then
		wrapped(C_DIM, t("filled_auto", table.concat(inputs.enemies, ", ", inputs.manual_n + 1)))
	end
	ui.separator_text(t("phase_mode"))
	ui.align_text_to_frame_padding()
	ui.text("%s", t("phase"))
	for _, p in ipairs({ "auto", "early", "mid", "late" }) do
		ui.same_line()
		if ui.radio((p == "auto" and t("auto") or t("phase_" .. p)) .. "##ph", cfg.phase == p) then cfg.phase = p; mark_dirty() end
	end
	local mode_items, mode_keys, midx = { t("auto") }, { "auto" }, 1
	for _, m in ipairs(DATA.modes) do
		mode_items[#mode_items + 1], mode_keys[#mode_keys + 1] = t("mode_" .. m.key), m.key
		if cfg.mode == m.key then midx = #mode_keys end
	end
	ui.set_next_item_width(220)
	local mi, mch = ui.combo(t("mode"), midx, mode_items)
	if mch then cfg.mode = mode_keys[mi]; mark_dirty() end
	owned_section()
	ui.spacing()
	ui.separator()
	update_result()
	draw_detailed(true)
end

