	v, c = ui.checkbox(t("set_show_tip"), cfg.show_tip)
	if c then cfg.show_tip = v; mark_dirty() end
	v, c = ui.checkbox(t("set_auto"), cfg.auto_detect)
	if c then cfg.auto_detect = v; mark_dirty() end
	v, c = ui.checkbox(t("set_live_items"), cfg.live_items)
	if c then cfg.live_items = v; mark_dirty() end
	ui.align_text_to_frame_padding()
	ui.text("%s", t("set_mode"))
	for _, d in ipairs({ "auto", "compact", "detailed" }) do
		ui.same_line()
		if ui.radio(t("disp_" .. d) .. "##disp", cfg.display == d) then cfg.display = d; mark_dirty() end
	end
	ui.set_next_item_width(220)
	v, c = ui.slider_float(t("set_opacity"), cfg.opacity, 0.2, 1.0, "%.2f")
	if c then cfg.opacity = v; mark_dirty() end
	ui.set_next_item_width(220)
	v, c = ui.slider_int(t("set_text"), cfg.text_size, 1, 3, ({ "S", "M", "L" })[cfg.text_size])
	if c then cfg.text_size = math.max(1, math.min(3, v)); mark_dirty() end
	v, c = ui.checkbox(t("set_lock"), cfg.locked)
	if c then cfg.locked = v; mark_dirty() end
	if ui.button(t("set_reset_pos")) then
		cfg.pos_x, cfg.pos_y, was_draggable = -1, -1, false
		mark_dirty()
	end
	ui.same_line()
	if ui.button(t("set_auto_width")) then
		cfg.overlay_w = { compact = 0, detailed = 0 }
		mark_dirty()
	end
	ui.same_line()
	if ui.button(t("set_tutorial")) then tut_step = 1 end
	ui.separator_text(t("set_keys"))
	ui.table("sc_keys", 3, { flags = ui.TableFlags.SizingStretchProp or 0 }, function()
		for _, a in ipairs(ACTIONS) do
			ui.push_id(a)
			ui.table_next_row()
			ui.table_next_column()
			ui.align_text_to_frame_padding()
			wrapped(nil, t("act_" .. a))
			ui.table_next_column()
			ui.align_text_to_frame_padding()
			if rebinding == a then tcol(C_ACCENT, "...") else tcol(C_ACCENT, cfg.keys[a]) end
			ui.table_next_column()
			if rebinding ~= a and ui.small_button(t("key_change")) then rebinding, rebind_msg = a, nil end
			if cfg.keys[a] ~= DEFAULT_KEYS[a] then
				ui.same_line()
				if ui.small_button(t("key_default")) then
					local ok, err = rebind(a, DEFAULT_KEYS[a])
					rebind_msg, rebind_ok = ok and t("key_restored") or err, ok
				end
			end
			ui.pop_id()
		end
	end)
	if rebinding then wrapped(C_ACCENT, t("key_press")) end
	if rebind_msg then wrapped(rebind_ok and C_GOOD or C_WARN, rebind_msg) end
	wrapped(C_DIM, t("key_hint"))
	if rebinding then poll_rebind() end
end

