-- ------------------------------------------------------------------ frame
local draw_failed = false
ui.on_draw(function()
	local ok, err = pcall(function()
		local now = os.clock()
		local fs = FS()   -- font set of the language shown now (0.6: loaded on first use)
		if fs.state == "wait" then
			fs.state = "ready"
		elseif fs.state == "pending" and (not ui.ready or ui.ready()) then
			-- outside the draw callback: the atlas cannot grow while a frame is being built
			if tempest.queue and pcall(tempest.queue, function() load_fonts(fs, "queue") end) then
				fs.state, fs.queued_at = "queued", now
			else
				load_fonts(fs, "draw")
			end
		elseif fs.state == "queued" and now - (fs.queued_at or now) > 3 then
			load_fonts(fs, "draw (queue never ran)")
		end
		if cfg.show_tip and not S.tip_done then draw_tip(now) end
		if cfg.auto_detect and (overlay_on or menu_open) then
			local st = DET:poll(now)
			if st.status == "champ_select" and st.me then last_cs_me = st.me end
			-- new game: the manual item list of the previous match no longer applies
			if (st.status == "champ_select" or st.status == "match") and last_status ~= st.status
				and last_status ~= "champ_select" and next(cfg.owned) then
				cfg.owned = {}
				mark_dirty()
			end
			last_status = st.status
		end
		-- 0.5.1: no item reading at the end of a match / without a player (world being torn down)
		local dst = DET.state.status
		if cfg.live_items and (overlay_on or menu_open) and dst ~= "match_over" and dst ~= "no_player" then
			PLAYER:poll(now, log)
		end
		if overlay_on or menu_open then update_result() end
		with_theme(function()
			if overlay_on then draw_overlay(now) end
			if menu_open then draw_menu() end
		end)
		if dirty_at and now - dirty_at > 1.0 then save_now() end
	end)
	if not ok and not draw_failed then
		draw_failed = true
		log("draw error (logged once): %s", tostring(err))
	end
end)

-- ------------------------------------------------------------------ console commands
tempest.command("smartcounter", function()
	set_menu(not menu_open)
end, "Counter & Shop Helper: open / close the menu")

tempest.command("smartcounter_probe", function()
	local lines = DET:probe()
	local ok, more = pcall(PLAYER.probe, PLAYER)
	if ok then
		for _, l in ipairs(more) do lines[#lines + 1] = l end
	else
		lines[#lines + 1] = "items: probe failed: " .. tostring(more)
	end
	lines[#lines + 1] = string.format("lang: cfg=%s ui=%s game=%s (%s, ini %s) fonts=%s (%s) icons=%d dir=%s",
		cfg.lang, ui_lang(), GAME_LANG, GAME_LANG_SRC, tostring(GAME_LANG_CODE), tostring(FS().state),
		tostring(FS().name), icons_loaded, tostring(MOD_DIR))
	for _, l in ipairs(lines) do log("probe %s", l) end
	pcall(tempest.toast, string.format("Counter & Shop Helper probe: %d lines in the Tempest log", #lines))
end, "Counter & Shop Helper: detection report (log)")

tempest.command("smartcounter_selftest", function()
	local ok, expected = pcall(require, "lib.sc_expected")
	if not ok then
		log("selftest: sc_expected missing (%s)", tostring(expected))
		return
	end
	local good, total, fails = PRED:selftest(expected)
	for _, f in ipairs(fails) do log("selftest FAIL %s", f) end
	log("selftest %d/%d scenarios match the Python engine", good, total)
	pcall(tempest.toast, string.format("Counter & Shop Helper selftest: %d/%d OK", good, total))
end, "Counter & Shop Helper: compares the Lua engine with the Python engine")

-- Live item reading: every candidate property and its values (buy / upgrade an item, run it again).
tempest.command("smartcounter_items", function()
	local ok, lines = pcall(PLAYER.probe, PLAYER)
	if not ok then
		log("items: probe failed: %s", tostring(lines))
		return
	end
	for _, l in ipairs(lines) do log("%s", l) end
	pcall(tempest.toast, string.format("Counter & Shop Helper items: %d lines in the Tempest log", #lines))
end, "Counter & Shop Helper: live item / rank sources with their values (log)")

tempest.command("smartcounter_items_watch", function()
	PLAYER.watch = not PLAYER.watch
	PLAYER.last_raw = nil
	PLAYER:refresh()
	log("items watch %s", PLAYER.watch and "on (one log line per change)" or "off")
	pcall(tempest.toast, "Counter & Shop Helper items watch: " .. (PLAYER.watch and "on" or "off"))
end, "Counter & Shop Helper: log every change of the live item sources")

-- Game class list (LuaLS stubs) to find the real inventory / item rank field names of 8.1.
tempest.command("smartcounter_dumpsdk", function()
	local ok, classes, files = pcall(tempest.dump_sdk)
	if ok then
		log("dumpsdk: %s classes, %s files written to <mod>\\types\\sdk (%s)", tostring(classes), tostring(files),
			tostring(MOD_DIR))
		pcall(tempest.toast, string.format("Counter & Shop Helper: %s classes written (types\\sdk)", tostring(classes)))
	else
		log("dumpsdk failed: %s", tostring(classes))
	end
end, "Counter & Shop Helper: writes the game class list (to map item fields)")

